"""Bilingual labels. A label is either a plain string (shown as-is, e.g. user data) or a
``(japanese, english)`` tuple."""

LANGS = ('ja', 'en')


# Common Japanese account names (as typed by users / generated by the calculators) -> English.
# Unknown names are shown as typed.
